def summarize(values):
    total, bad = 0, 0
    for value in values:
        try:
            if isinstance(value, bool):
                raise ValueError('booleans are not numbers')
            number = int(value)
            if number < 0:
                raise ValueError('negative number')
            total += number
        except (ValueError, TypeError):
            bad += 1
    return total, bad

assert summarize([]) == (0, 0)
assert summarize([True, -1, 'oops', None]) == (0, 4)
print(summarize(['10', 'oops', '20', None, '30']))

from dataclasses import dataclass

@dataclass(frozen=True)
class Invoice:
    invoice_id: str
    amount: float

def parse_invoice(record: dict) -> Invoice:
    try:
        amount = float(record['amount'])
    except (KeyError, TypeError, ValueError) as err:
        raise ValueError('amount must be a number') from err
    if amount < 0:
        raise ValueError('amount cannot be negative')
    return Invoice(str(record['invoice_id']), amount)

assert parse_invoice({'invoice_id':1,'amount':'8'}).amount == 8
try:
    parse_invoice({'invoice_id':2,'amount':'oops'})
except ValueError as err:
    print(str(err))

from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()

class Invoice(BaseModel):
    amount: float = Field(ge=0)
    days_overdue: int = Field(ge=0)


def risk_rule(days_overdue: int) -> bool:
    return days_overdue >= 30

@app.get('/health')
def health():
    return {'status': 'ok'}

@app.post('/score')
def score(invoice: Invoice):
    return {'risk_flag': risk_rule(invoice.days_overdue), 'kind': 'rule_only'}

from fastapi.testclient import TestClient
from main import app

client = TestClient(app)

def test_health():
    r = client.get('/health')
    assert r.status_code == 200 and r.json() == {'status': 'ok'}

def test_score():
    r = client.post('/score', json={'amount': 200, 'days_overdue': 45})
    assert r.status_code == 200 and r.json()['risk_flag'] is True

def test_invalid():
    r = client.post('/score', json={'amount': -1, 'days_overdue': 45})
    assert r.status_code == 422
